fpath = os.path.join(sessions_dir, '01a181db-6ce9-725b-a3da-234ed1744387.jsonl')

with open(fpath) as f:
    content = f.read()

lines = content.split('\n')

# Extract JSON objects and look for 'Demo pair' in text content
demo_data = []
i = 0
while i < len(lines):
    line = lines[i]
    # Check if this line contains Demo pair (in the text portion)
    if 'Demo pair' in line:
        # Try to find the full JSON object starting from here
        # Find the matching braces
        brace_count = line.count('{') - line.count('}')
        j = i
        while brace_count != 0:
            j += 1
            if j < len(lines):
                brace_count += lines[j].count('{') - lines[j].count('}')
        json_obj = '\n'.join(lines[i:j+1])

        # Try to parse as JSON
        try:
            msg = json.loads(json_obj)
            # Look for content in text format
            for key in msg:
                if 'text' in key.lower() or 'content' in key.lower():
                    val = msg[key]
                    if isinstance(val, dict):
                        if 'text' in val:
                            text = val['text']
                            if 'Demo pair' in text:
                                # Extract the grid portion from text
                                if 'Demo pair' in text:
